SELECT p.close_reason, COUNT(*) AS n, SUM(p.realized_pnl<0) AS losses, ROUND(SUM(p.realized_pnl),4) AS pnl_usdt, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100),4) AS avg_ret_pct, ROUND(MIN((p.exit_price-p.entry_price)/p.entry_price*100),4) AS worst_ret_pct, ROUND(AVG(UNIX_TIMESTAMP(p.closed_at)-UNIX_TIMESTAMP(p.opened_at)),0) AS avg_hold_s FROM crypto_ai.paper_position p WHERE p.status='CLOSED' AND p.closed_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400) GROUP BY p.close_reason ORDER BY n DESC LIMIT 20;